// GENERATED by scripts/embed-host-script.sh from host/macmosh-host. Do not edit by hand.
// After any change to host/macmosh-host, regenerate it with: scripts/embed-host-script.sh
// (scripts/check.sh fails when this file is out of date.)

enum HostScriptSource {
    static let text = #"""
#!/bin/bash
# macmosh-host: the script MacMosh keeps on a workhorse (a Mac you reach from another Mac).
# It starts the desk server, prints the status report, manages desks and installs the login agent.
# Plain bash 3.2 (what macOS ships at /bin/bash): no associative arrays, no mapfile, no ${var,,}.
set -u

MACMOSH_HOST_VERSION=0.11.0
MACMOSH_PROTOCOL=1
AGENT_LABEL=io.github.shariqh.macmosh.host

MACMOSH_HOME="${MACMOSH_HOME:-$HOME/.macmosh}"
MACMOSH_SOCKET="${MACMOSH_SOCKET:-macmosh}"
# Homebrew's folders go at the END of PATH, so a stand-in tool earlier on PATH wins in tests.
PATH="$PATH:/opt/homebrew/bin:/usr/local/bin"
export MACMOSH_HOME MACMOSH_SOCKET PATH

TAB=$'\t'

# Every tmux call goes through this one function, so it always names the desk server's socket.
mm_tmux() { command tmux -L "$MACMOSH_SOCKET" "$@"; }

# ---------------------------------------------------------------- log

# One line per subcommand: an ISO 8601 time, the subcommand and the result.
# The log never makes a subcommand fail, and it is cut back when it grows past about 1 MB.
mm_log() {
    local log="$MACMOSH_HOME/host.log" size
    mkdir -p "$MACMOSH_HOME" 2>/dev/null || return 0
    if [ -f "$log" ]; then
        size=$(wc -c < "$log" 2>/dev/null | tr -d ' ')
        if [ "${size:-0}" -gt 1000000 ]; then
            tail -n 2000 "$log" > "$log.$$.tmp" 2>/dev/null && mv "$log.$$.tmp" "$log" 2>/dev/null
        fi
    fi
    printf '%s\t%s\t%s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$1" "$2" >> "$log" 2>/dev/null
    return 0
}

# ---------------------------------------------------------------- small helpers

# Tabs and newlines become spaces, so one value can never break the record around it.
mm_clean() { printf '%s' "$1" | tr '\t\n\r' '   '; }

mm_valid_desk_name() {
    case "$1" in
        '' | *[!A-Za-z0-9_-]*) return 1 ;;
    esac
    [ "${#1}" -le 64 ]
}

mm_server_up() { mm_tmux list-sessions >/dev/null 2>&1; }

# The user logged in at the screen, or nothing.
mm_console_user() {
    local who
    who=$(stat -f %Su /dev/console 2>/dev/null)
    case "$who" in
        root | loginwindow | _mbsetupuser) who="" ;;
    esac
    printf '%s' "$who"
}

# ---------------------------------------------------------------- start

# The file tmux itself would read: ~/.tmux.conf, otherwise the XDG one.
mm_user_tmux_conf() {
    if [ -f "$HOME/.tmux.conf" ]; then
        printf '%s' "$HOME/.tmux.conf"
    else
        printf '%s' "${XDG_CONFIG_HOME:-$HOME/.config}/tmux/tmux.conf"
    fi
}

mm_write_tmux_conf() {
    mkdir -p "$MACMOSH_HOME" || return 1
    {
        echo '# MacMosh defaults. Your own tmux settings are loaded next, so your settings win,'
        echo '# except the two after them that desks need: the server stays up with no desk open,'
        echo '# and a desk stays open when its last terminal leaves.'
        echo 'set -g mouse on'
        echo 'set -g history-limit 50000'
        echo "source-file -q \"$(mm_user_tmux_conf)\""
        echo 'set -s exit-empty off'
        echo 'set -g destroy-unattached off'
    } > "$MACMOSH_HOME/tmux.conf"
}

cmd_start() {
    if mm_server_up; then
        mm_set_hook
        mm_log start "already up"
        return 0
    fi
    if ! mm_write_tmux_conf; then
        mm_log start "failed: cannot write tmux.conf"
        echo "macmosh-host: cannot write $MACMOSH_HOME/tmux.conf" >&2
        return 5
    fi
    mm_tmux -f "$MACMOSH_HOME/tmux.conf" start-server >/dev/null 2>&1
    if mm_server_up; then
        # The hook first, so a reopened desk whose shell ends at once is handled like any other.
        # Nothing is dropped here: a server that was down says nothing about why, so every
        # definition stays. A line that is not reopened is hidden by the menu, desk-new replaces it,
        # and attach makes the desk again from it.
        mm_set_hook
        mm_reopen_desks
        mm_log start "started"
        return 0
    fi
    mm_log start "failed: server did not start"
    echo "macmosh-host: the desk server did not start" >&2
    return 5
}

# ---------------------------------------------------------------- desks

DESKS_FILE_NAME=desks.tsv

mm_desks_file() { printf '%s' "$MACMOSH_HOME/$DESKS_FILE_NAME"; }

# A leading ~ (alone or before a slash) means the home folder. Anything else is left as it is.
mm_expand_tilde() {
    local tilde='~'
    case "$1" in
        "$tilde") printf '%s' "$HOME" ;;
        "$tilde"/*) printf '%s' "$HOME/${1#"$tilde"/}" ;;
        *) printf '%s' "$1" ;;
    esac
}

# True when the text has a tab or a newline in it, which would break a line of desks.tsv.
mm_has_tab_or_newline() {
    case "$1" in
        *"$TAB"* | *$'\n'*) return 0 ;;
    esac
    return 1
}

# Every awk that compares a desk name with the first field adds "" to both sides. Without it awk
# compares names that look like numbers as numbers, so "7" would match "007" and "1000" would match "1e3".

# The line of desks.tsv for one desk, or nothing.
mm_def_line() {
    local file
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    awk -F '\t' -v n="$1" '($1 "") == (n "") { print; exit }' "$file"
}

# The tmux id ($n) of the session with exactly this name, or nothing. Not has-session -t "=name": when
# no session has the name, tmux also matches it against an attached client's tty (ttys003), and then
# stands for the session that client shows.
# A view (a session tagged @macmosh-view, see mm_open_view) is never a desk, even when tmux's own rename
# (prefix and $, in a tab) has given it a desk's name.
mm_session_id() {
    mm_tmux list-sessions -F "#{session_id}$TAB#{@macmosh-view}$TAB#{session_name}" 2>/dev/null |
        awk -F '\t' -v n="$1" '{ id = $1; tag = $2; sub(/^[^\t]*\t[^\t]*\t/, "") }
            tag == "" && ($0 "") == (n "") { print id; exit }'
}

mm_session_exists() { [ -n "$(mm_session_id "$1")" ]; }

# One format of the session with this id ($n), or nothing when there is no such session. Read through
# list-sessions: display-message answers even for a session or a window that does not exist (seen with
# tmux 3.8), so it can't tell.
mm_session_field() {
    mm_tmux list-sessions -F "#{session_id}$TAB$2" 2>/dev/null |
        awk -F '\t' -v id="$1" '($1 "") == (id "") { sub(/^[^\t]*\t/, ""); print; exit }'
}

# True when the session with id $1 has the window with id $2 (@n).
mm_session_has_window() {
    mm_tmux list-windows -t "$1:" -F '#{window_id}' 2>/dev/null | grep -qxF -- "$2"
}

# True when a session or a session group already has this name.
mm_name_in_use() {
    mm_tmux list-sessions -F "#{session_name}$TAB#{session_group}" 2>/dev/null |
        awk -F '\t' -v n="$1" '($1 "") == (n "") || ($2 "") == (n "") { found = 1 } END { exit !found }'
}

# Reads one line of desks.tsv into d_name, d_reopen, d_keep, d_permanent, d_folder and d_command.
# A line is: name, reopen (0 or 1), keep (0 or 1), permanent (0 or 1), folder, startup command.
# A line written before 0.5.0 has no permanent field: its folder comes fourth. A folder always starts
# with /, which tells the two apart, and a desk from such a line is not permanent.
mm_read_def() {
    local rest="$1"
    d_name="" d_reopen="" d_keep="" d_permanent=0 d_folder="" d_command=""
    d_name="${rest%%"$TAB"*}"
    [ "$d_name" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    d_reopen="${rest%%"$TAB"*}"
    [ "$d_reopen" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    d_keep="${rest%%"$TAB"*}"
    [ "$d_keep" != "$rest" ] || return 0
    rest="${rest#*"$TAB"}"
    case "$rest" in
        /*) ;;
        *"$TAB"*)
            d_permanent="${rest%%"$TAB"*}"
            rest="${rest#*"$TAB"}"
            ;;
    esac
    d_folder="${rest%%"$TAB"*}"
    if [ "$d_folder" != "$rest" ]; then d_command="${rest#*"$TAB"}"; fi
    return 0
}

# Writes desks.tsv without the line for one desk, through a temporary file and mv. The caller holds the lock.
mm_drop_def_line() {
    local file tmp
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
    if ! awk -F '\t' -v n="$1" '($1 "") != (n "")' "$file" > "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        return 1
    fi
    return 0
}

# The desk server's process id, or nothing when no server answers. It never starts a server.
mm_server_pid() { mm_tmux display-message -p '#{pid}' 2>/dev/null; }

# --- Removing a desk when its last shell exits.
#
# The desk server runs a hook when a session closes. It waits a moment, then runs
# "<this script> desk-closed <desk> <server pid>", and desk-closed removes the desk's definition only
# when that same server still answers. An exit in a desk's last shell leaves the server running (its
# exit-empty is off). Shutting the server down (kill-server, restart-server, a signal, the Mac
# restarting) ends it, so a hook from it finds no server or a different one, and the definition stays.
# Seen with tmux 3.8: a server that is shutting down runs no session-closed hook at all.
#
# The wait is a minute. It runs inside the desk server, so a restart or a logout that ends the server
# within that minute ends the wait too, and the definition stays. At an Apple-menu restart or logout,
# macOS first quits the apps, which can take a while, and only then ends the server; a desk whose
# program waited on one of those apps closes in between. The cost: after a real exit, the stale line
# stays (hidden by the menu) for up to a minute, and a desk exited less than a minute before a restart
# comes back once. MACMOSH_HOOK_DELAY (whole seconds) changes the wait, for the tests.
#
# The hook lives in one member of the session-closed hook array, so the user's own hooks stay. start,
# status, attach, desk-new and window-new set it again each time: a server started by an older script
# gets it with no restart, and a hook cleared by reloading the user's tmux settings comes back.
MM_HOOK='session-closed[1089]'
MM_HOOK_DELAY="${MACMOSH_HOOK_DELAY:-60}"
case "$MM_HOOK_DELAY" in
    '' | *[!0-9]*) MM_HOOK_DELAY=60 ;;
esac

mm_set_hook() {
    local prefix
    prefix="MACMOSH_HOME=$(mm_shell_quote "$MACMOSH_HOME") MACMOSH_SOCKET=$(mm_shell_quote "$MACMOSH_SOCKET")"
    prefix="$prefix $(mm_shell_quote "$(mm_self_path)") desk-closed"
    # The prefix is kept in a user option and put into the command when the hook runs, so a path with
    # odd characters never passes through tmux's own command parser. q: quotes the desk name and the
    # session id ($n) for sh; the id tells desk-closed when the session was a view (see mm_open_view).
    # destroy-unattached is forced off here too (see mm_write_tmux_conf), for a server that is already
    # running or whose user settings were loaded again.
    # shellcheck disable=SC2016  # the #{...} parts are tmux formats, expanded when the hook runs
    mm_tmux set-option -g destroy-unattached off \; \
        set-option -g @macmosh-desk-closed "$prefix" \; \
        set-hook -g "$MM_HOOK" "run-shell -b -d $MM_HOOK_DELAY '#{@macmosh-desk-closed} #{q:hook_session_name} #{pid} #{q:hook_session} >/dev/null 2>&1 || true'" \
        >/dev/null 2>&1
    return 0
}

# This script's own full path, so a desk can run it again later.
mm_self_path() {
    local p="$0"
    case "$p" in
        */*) ;;
        *) p=$(command -v -- "$p" 2>/dev/null || printf '%s' "$p") ;;
    esac
    case "$p" in
        /*) ;;
        *) p="$PWD/${p#./}" ;;
    esac
    printf '%s' "$p"
}

# Text quoted for a shell: inside single quotes, with each ' written as '\''.
mm_shell_quote() {
    local text="$1" quote="'" out=""
    while :; do
        case "$text" in
            *"$quote"*)
                out="$out${text%%"$quote"*}'\''"
                text="${text#*"$quote"}"
                ;;
            *) break ;;
        esac
    done
    printf "'%s'" "$out$text"
}

# Creates the session for a desk: in its folder, then types the startup command exactly as written.
# For a desk that keeps its command running, it types "<this script> keep <desk>" instead, and that
# runs the command again whenever it ends.
# The keys wait in the terminal's input queue, so a shell that is slow to start still receives them.
# The keys go to the new session's id, never "=name" (see mm_session_id). MM_NEW_SID holds that id, or
# nothing when no session was made, so a caller that rolls back kills only the session made here.
#
# The session is born in a session group of its own, which its views join later (see mm_open_view). A
# group keeps the name it was made with for good, and a new session asked to join a name that a group
# has joins that group (both seen with tmux 3.8). So the name is one no desk can have and no other group
# has: "macmosh+g" and the number of the id the session is about to get. Every caller holds the desk
# list's lock, as mm_open_view does, so no other MacMosh session is made in between. tmux before 3.3
# has no next_session_id; then the name is made of this process, the time and a count, because one
# start reopens several desks within a second.
MM_GROUP_COUNT=0
mm_create_session() {
    # $1 name, $2 folder, $3 startup command (may be empty), $4 keep: 1 or 0 (optional)
    local folder="$2" typed="$3" sid next group
    MM_NEW_SID=""
    MM_GROUP_COUNT=$((MM_GROUP_COUNT + 1))
    next=$(mm_tmux display-message -p '#{next_session_id}' 2>/dev/null)
    group="macmosh+g${next#\$}"
    if [ -z "$next" ] || mm_name_in_use "$group"; then group="macmosh+g$$-$(date +%s)-$MM_GROUP_COUNT"; fi
    if mm_name_in_use "$group"; then return 1; fi
    if [ ! -d "$folder" ]; then
        mm_log "create-desk" "$1: folder is gone, using the home folder"
        folder="$HOME"
    fi
    if [ "${4:-0}" = 1 ] && [ -n "$typed" ]; then
        typed="$(mm_shell_quote "$(mm_self_path)") keep $1"
    fi
    sid=$(mm_tmux new-session -d -P -F '#{session_id}' -s "$1" -t "$group" -c "$folder" 2>/dev/null) || return 1
    MM_NEW_SID="$sid"
    [ -n "$sid" ] || return 1
    if [ -n "$typed" ]; then
        mm_tmux send-keys -t "$sid:" -l -- "$typed" || return 1
        mm_tmux send-keys -t "$sid:" Enter || return 1
    fi
    return 0
}

# Recreates the desks marked reopen. Called by start, only when it has just started the server.
# This includes a permanent desk that was closed: it is marked reopen, so it opens again.
# Each desk is made under the desk list's lock, with its line read again there, so a desk-new or a
# desk-remove of the same name running at the same moment goes wholly before or wholly after it.
# The loop reads the list it opened, which a desk-rename replaces with mv, so a second pass over the
# current list opens a desk renamed during the first. It skips the names the first pass handled.
# Accepted: a desk made or renamed during the first pass and then exited before the second pass
# reaches it is opened once more.
mm_reopen_desks() {
    MM_REOPENED=""
    mm_reopen_pass 1
    mm_reopen_pass 2
    return 0
}

# One pass of mm_reopen_desks. Pass 1 records each name in MM_REOPENED; pass 2 skips those names.
mm_reopen_pass() {
    local file line name
    file=$(mm_desks_file)
    [ -f "$file" ] || return 0
    while IFS= read -r line || [ -n "$line" ]; do
        mm_read_def "$line"
        mm_valid_desk_name "$d_name" || continue
        [ "$d_reopen" = 1 ] || continue
        name="$d_name"
        case "$MM_REOPENED" in
            *" $name "*) continue ;;
        esac
        if [ "$1" = 1 ]; then MM_REOPENED="$MM_REOPENED $name "; fi
        if ! mm_lock; then
            mm_log start "could not reopen $name: could not lock the desk list"
            continue
        fi
        line=$(mm_def_line "$name")
        if [ -n "$line" ]; then mm_read_def "$line"; fi
        if [ -n "$line" ] && [ "$d_reopen" = 1 ] && ! mm_session_exists "$name"; then
            mm_create_session "$name" "$d_folder" "$d_command" "$d_keep" || mm_log start "could not reopen $name"
        fi
        mm_release_lock
    done < "$file"
    return 0
}

# --- The lock around desks.tsv: a folder made with mkdir. One writer at a time. A lock folder older
# than 30 seconds belongs to a writer that died, so it is removed.

MM_LOCK_HELD=0

mm_unlock() {
    if [ "$MM_LOCK_HELD" = 1 ]; then
        MM_LOCK_HELD=0
        rmdir "$MACMOSH_HOME/lock" 2>/dev/null
    fi
    return 0
}

# Takes the lock, waiting up to 5 seconds. Releases it on every way out (the trap), including
# an error part-way and a signal.
mm_lock() {
    local lock="$MACMOSH_HOME/lock" tries=0 mtime now
    mkdir -p "$MACMOSH_HOME" || return 1
    while ! mkdir "$lock" 2>/dev/null; do
        mtime=$(/usr/bin/stat -f %m "$lock" 2>/dev/null)
        case "$mtime" in
            '' | *[!0-9]*) mtime="" ;;
        esac
        now=$(date +%s)
        if [ -n "$mtime" ] && [ $((now - mtime)) -gt 30 ] && rmdir "$lock" 2>/dev/null; then
            continue
        fi
        tries=$((tries + 1))
        [ "$tries" -lt 50 ] || return 1
        sleep 0.1
    done
    MM_LOCK_HELD=1
    trap mm_unlock EXIT
    trap 'exit 130' INT HUP
    trap 'exit 143' TERM
    return 0
}

mm_release_lock() {
    mm_unlock
    trap - EXIT INT HUP TERM
}

# If the desk server is down: with nobody logged in at the screen, exit 3. Otherwise ask macOS to
# run the login agent, wait up to 5 seconds, and exit 5 if the server is still down.
# This is the only way these subcommands get a server. They never start one themselves, because a
# tmux server started from an ssh login can't read the keychain.
mm_require_server() {
    # $1 the subcommand, for the log
    local who n=0
    if mm_server_up; then return 0; fi
    who=$(mm_console_user)
    if [ -z "$who" ]; then
        echo "Nobody is logged in at this Mac's screen, so desks can't start. Log in first." >&2
        mm_log "$1" "nobody logged in"
        exit 3
    fi
    launchctl kickstart "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1
    while [ "$n" -lt 10 ]; do
        if mm_server_up; then return 0; fi
        sleep 0.5
        n=$((n + 1))
    done
    if mm_server_up; then return 0; fi
    echo "The desk server didn't start." >&2
    mm_log "$1" "server did not start"
    exit 5
}

# A usage error: a message, a log line and exit 2.
mm_usage_error() {
    # $1 subcommand, $2 message
    echo "macmosh-host: $2" >&2
    mm_log "$1" "usage error"
    exit 2
}

cmd_desk_new() {
    local name="" folder="" reopen=1 keep=0 permanent=0 command="" npos=0 file tmp old
    while [ $# -gt 0 ]; do
        case "$1" in
            # A new desk comes back after a restart unless told not to. --reopen is still accepted.
            --reopen) reopen=1 ;;
            --no-reopen) reopen=0 ;;
            --keep) keep=1 ;;
            --permanent) permanent=1 ;;
            --command)
                [ $# -ge 2 ] || mm_usage_error desk-new "--command needs a value"
                command="$2"
                shift
                ;;
            --*) mm_usage_error desk-new "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                case "$npos" in
                    1) name="$1" ;;
                    2) folder="$1" ;;
                    *) mm_usage_error desk-new "too many arguments" ;;
                esac
                ;;
        esac
        shift
    done
    [ "$npos" -eq 2 ] || mm_usage_error desk-new "usage: desk-new <name> <folder> [--no-reopen] [--permanent] [--keep] [--command <text>]"

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: a desk name uses letters, digits, - and _ only, up to 64 characters" >&2
        mm_log desk-new "refused: bad name"
        return 6
    fi
    # Check before expanding: $(...) drops a new line at the end of the text.
    if mm_has_tab_or_newline "$folder" || mm_has_tab_or_newline "$command"; then
        echo "macmosh-host: a folder or command can't contain a tab or a new line" >&2
        mm_log desk-new "refused: tab or newline"
        return 6
    fi
    if [ "$keep" = 1 ] && [ -z "$command" ]; then
        echo "macmosh-host: there is nothing to keep running: --keep needs a --command" >&2
        mm_log desk-new "refused: keep without a command"
        return 6
    fi
    folder=$(mm_expand_tilde "$folder")
    case "$folder" in
        /*) ;;
        *)
            echo "macmosh-host: the folder must be a full path or start with ~" >&2
            mm_log desk-new "refused: folder is not a full path"
            return 6
            ;;
    esac
    if [ ! -d "$folder" ]; then
        echo "macmosh-host: no such folder: $folder" >&2
        mm_log desk-new "refused: no such folder"
        return 6
    fi

    mm_require_server desk-new
    mm_set_hook

    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-new "failed: lock"
        return 1
    fi
    # The name is taken by an open desk, or by a permanent one that is closed. A line that is neither
    # is left over (its last shell exited, or it ended with an older server) and is replaced.
    old=$(mm_def_line "$name")
    if [ -n "$old" ]; then mm_read_def "$old"; fi
    if mm_session_exists "$name" || { [ -n "$old" ] && [ "$d_permanent" != 0 ]; }; then
        mm_release_lock
        echo "macmosh-host: the desk $name already exists" >&2
        mm_log desk-new "refused: $name already exists"
        return 7
    fi
    # Save the definition first. The desk's shell may run "keep <desk>" the moment the session exists,
    # and keep reads this line. If the session can't be made, the line is taken back out.
    file=$(mm_desks_file)
    tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
    if ! {
        { [ ! -f "$file" ] || awk -F '\t' -v n="$name" '($1 "") != (n "")' "$file"; } &&
            printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$name" "$reopen" "$keep" "$permanent" "$folder" "$command"
    } > "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        mm_release_lock
        echo "macmosh-host: could not write the desk list" >&2
        mm_log desk-new "failed: $name could not be saved"
        return 1
    fi
    if ! mm_create_session "$name" "$folder" "$command" "$keep"; then
        if [ -n "$MM_NEW_SID" ]; then mm_tmux kill-session -t "$MM_NEW_SID" >/dev/null 2>&1; fi
        mm_drop_def_line "$name"
        mm_release_lock
        echo "macmosh-host: could not create the desk" >&2
        mm_log desk-new "failed: $name could not be created"
        return 1
    fi
    mm_release_lock
    mm_log desk-new "created $name"
    return 0
}

cmd_desk_remove() {
    local name="" kill=0 npos=0 had_def=0 had_session=0 sid
    while [ $# -gt 0 ]; do
        case "$1" in
            --kill) kill=1 ;;
            --*) mm_usage_error desk-remove "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                [ "$npos" -le 1 ] || mm_usage_error desk-remove "too many arguments"
                name="$1"
                ;;
        esac
        shift
    done
    [ "$npos" -eq 1 ] || mm_usage_error desk-remove "usage: desk-remove <name> [--kill]"

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log desk-remove "no such desk"
        return 4
    fi
    # No mm_require_server here: removing a desk never needs a server, and must never start one.
    # has-session and kill-session only talk to a server that is already running.
    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-remove "failed: lock"
        return 1
    fi
    if [ -n "$(mm_def_line "$name")" ]; then had_def=1; fi
    sid=$(mm_session_id "$name")
    if [ -n "$sid" ]; then had_session=1; fi
    if [ "$had_def" = 0 ] && { [ "$kill" = 0 ] || [ "$had_session" = 0 ]; }; then
        mm_release_lock
        echo "macmosh-host: no such desk: $name" >&2
        mm_log desk-remove "no such desk: $name"
        return 4
    fi
    if [ "$had_def" = 1 ]; then
        if ! mm_drop_def_line "$name"; then
            mm_release_lock
            echo "macmosh-host: could not write the desk list" >&2
            mm_log desk-remove "failed: $name could not be saved"
            return 1
        fi
    fi
    # The desk's views first, each by its id, while the lock keeps a new one from being made. A view
    # left behind would keep the desk's windows running. kill-session without -g closes only windows
    # that no other session shows, so the desk's own session goes last and takes the windows.
    if [ "$kill" = 1 ] && [ "$had_session" = 1 ]; then
        mm_kill_views "$sid"
        mm_tmux kill-session -t "$sid" >/dev/null 2>&1
    fi
    mm_release_lock
    mm_log desk-remove "removed $name"
    return 0
}

# Renames a desk: its tmux session, if it has one, and the first field of its definition, if it has
# one. Everything else stays: the windows and what runs in them, the folder, the startup command and
# the reopen, keep and permanent fields. A rename closes no session, so the exit path never runs for it.
# With the desk server up, the new name is taken by an open desk or a permanent one, as for desk-new,
# and a line that is neither is left over from an exit and is replaced. With no server, any line takes
# it, because the desk waits to reopen at the next login.
cmd_desk_rename() {
    local old new taken file tmp up sid line
    [ $# -eq 2 ] || mm_usage_error desk-rename "usage: desk-rename <name> <new name>"
    old="$1"
    new="$2"
    if ! mm_valid_desk_name "$old" || ! mm_valid_desk_name "$new"; then
        mm_usage_error desk-rename "a desk name uses letters, digits, - and _ only, up to 64 characters"
    fi
    # No mm_require_server here, as for desk-remove: a closed desk is renamed in the list alone, and
    # has-session and rename-session only talk to a server that is already running.
    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log desk-rename "failed: lock"
        return 1
    fi
    # Sessions are found by id, never by "=name" (see mm_session_id). With a server up, a closed desk
    # that is not permanent has exited and its line only waits for the exit path, so it is no desk to
    # rename. With none, every line is a desk waiting for the next login.
    up=0
    if mm_server_up; then up=1; fi
    sid=$(mm_session_id "$old")
    line=$(mm_def_line "$old")
    if [ -n "$line" ]; then mm_read_def "$line"; fi
    if [ -z "$sid" ] && { [ -z "$line" ] || { [ "$up" = 1 ] && [ "$d_permanent" = 0 ]; }; }; then
        mm_release_lock
        echo "macmosh-host: no such desk: $old" >&2
        mm_log desk-rename "no such desk: $old"
        return 4
    fi
    # The new name is taken by an open desk, a permanent one, or, with no server, any line.
    taken=$(mm_def_line "$new")
    if [ -n "$taken" ]; then mm_read_def "$taken"; fi
    if [ "$old" = "$new" ] || [ -n "$(mm_session_id "$new")" ] ||
        { [ -n "$taken" ] && { [ "$d_permanent" != 0 ] || [ "$up" = 0 ]; }; }; then
        mm_release_lock
        echo "macmosh-host: the desk $new already exists" >&2
        mm_log desk-rename "refused: $new already exists"
        return 7
    fi
    if [ -n "$sid" ] && ! mm_tmux rename-session -t "$sid" -- "$new" >/dev/null 2>&1; then
        mm_release_lock
        echo "macmosh-host: could not rename the desk $old" >&2
        mm_log desk-rename "failed: the session $old was not renamed"
        return 1
    fi
    # The list: the old name's line gets the new name, and a leftover line for the new name goes.
    # substr keeps the rest of the line byte for byte.
    file=$(mm_desks_file)
    if [ -f "$file" ]; then
        tmp="$MACMOSH_HOME/$DESKS_FILE_NAME.$$.tmp"
        if ! awk -F '\t' -v o="$old" -v n="$new" '
                ($1 "") == (n "") { next }
                ($1 "") == (o "") { print n substr($0, length($1) + 1); next }
                { print }' "$file" > "$tmp" || ! mv "$tmp" "$file"; then
            rm -f "$tmp"
            # Put the session's name back, so the desk and its definition still agree.
            if [ -n "$sid" ]; then mm_tmux rename-session -t "$sid" -- "$old" >/dev/null 2>&1; fi
            mm_release_lock
            echo "macmosh-host: could not write the desk list" >&2
            mm_log desk-rename "failed: $old could not be saved"
            return 1
        fi
    fi
    # The desk's views, found by their tag, show the new name in their bars (see mm_view_bar).
    if [ -n "$sid" ]; then mm_name_views "$sid" "$new"; fi
    mm_release_lock
    mm_log desk-rename "renamed $old to $new"
    return 0
}

# Run by the desk server's session-closed hook (see mm_set_hook), a moment after a desk's session
# closed: removes the desk's definition, unless the desk is permanent. When anything is unclear the
# definition stays, because a definition removed by mistake is a desk that won't come back after a
# restart, while one kept by mistake is only a name that desk-new replaces and the menu doesn't show.
# It stays when: another server answers or none does (the server went away: a restart, kill-server,
# a signal), nobody is logged in at the screen (logging out), the desk is open again, or it is permanent.
# The closed session's id comes third (a hook set by a script before 0.7.0 leaves it out). A view's id
# was recorded on the server when it was made, so a view is ignored whatever name it had when it closed.
cmd_desk_closed() {
    local name pid line id="" key
    [ $# -eq 2 ] || [ $# -eq 3 ] || mm_usage_error desk-closed "usage: desk-closed <desk> <desk server pid> [<session id>]"
    name="$1"
    pid="$2"
    [ $# -lt 3 ] || id="$3"
    case "$id" in
        '$'[0-9]*)
            key="@macmosh-view-${id#\$}"
            case "$key" in
                *[!0-9a-z@-]*) ;;
                *)
                    if [ "$(mm_server_pid)" = "$pid" ] && [ -n "$(mm_tmux show-options -sqv "$key" 2>/dev/null)" ]; then
                        mm_tmux set-option -su "$key" >/dev/null 2>&1
                        mm_log desk-closed "ignored: a view"
                        return 0
                    fi
                    ;;
            esac
            ;;
    esac
    if ! mm_valid_desk_name "$name"; then
        mm_log desk-closed "ignored: not a desk name"
        return 0
    fi
    case "$pid" in
        '' | *[!0-9]*)
            mm_log desk-closed "kept $name: no server pid"
            return 0
            ;;
    esac
    [ -n "$(mm_def_line "$name")" ] || return 0
    if [ "$(mm_server_pid)" != "$pid" ]; then
        mm_log desk-closed "kept $name: the desk server went away"
        return 0
    fi
    if ! mm_lock; then
        mm_log desk-closed "kept $name: could not lock the desk list"
        return 1
    fi
    # Read again under the lock: desk-new or desk-remove may have changed the line in the meantime.
    line=$(mm_def_line "$name")
    if [ -z "$line" ]; then
        mm_release_lock
        return 0
    fi
    mm_read_def "$line"
    if [ "$d_permanent" != 0 ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: permanent"
        return 0
    fi
    if mm_session_exists "$name"; then
        mm_release_lock
        mm_log desk-closed "kept $name: open again"
        return 0
    fi
    # Last, the screen and the server once more, just before the write: has-session also fails when the
    # server has just gone, and a logout or shutdown may have begun while this waited for the lock.
    if [ -z "$(mm_console_user)" ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: nobody is logged in at the screen"
        return 0
    fi
    if [ "$(mm_server_pid)" != "$pid" ]; then
        mm_release_lock
        mm_log desk-closed "kept $name: the desk server went away"
        return 0
    fi
    if ! mm_drop_def_line "$name"; then
        mm_release_lock
        mm_log desk-closed "kept $name: could not write the desk list"
        return 1
    fi
    mm_release_lock
    mm_log desk-closed "removed $name: its last shell exited"
    return 0
}

cmd_window_new() {
    local name sid
    [ $# -eq 1 ] || mm_usage_error window-new "usage: window-new <desk>"
    name="$1"
    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log window-new "no such desk"
        return 4
    fi
    mm_require_server window-new
    mm_set_hook
    sid=$(mm_session_id "$name")
    if [ -z "$sid" ]; then
        echo "macmosh-host: the desk $name isn't open" >&2
        mm_log window-new "no such desk: $name"
        return 4
    fi
    if ! mm_tmux new-window -t "$sid:" >/dev/null 2>&1; then
        echo "macmosh-host: could not add a window" >&2
        mm_log window-new "failed: $name"
        return 1
    fi
    mm_log window-new "added a window to $name"
    return 0
}

# --- Naming one window of a desk (issue 144, 0.11.0).
#
# window-name <desk> <window id> <name> renames that window; --auto in place of the name gives the name
# back to tmux, which then names the window after the program running in it. The window is the same
# window in the desk's session and in every view of it, so the name shows in all of them, in the report's
# window lines and in the bar tmux draws at the bottom of a tab. Seen with tmux 3.8 on a throwaway socket
# (WindowNameTests): rename-window turns the window's own automatic-rename off, as the manual says, so the
# name stays while other programs run; turning it on again names the window after its program at once;
# and rename-window expands a format in the name it is given, so # is never let through. Names are not
# kept across a restart: a desk comes back as one fresh window.

# True when $1 can be a window's name: 1 to 32 characters, each a letter, a digit, a space, -, _ or a
# full stop, not starting or ending with a space. The characters are listed one by one, because a range
# such as a-z can take in other letters in some locales.
mm_valid_window_name() {
    case "$1" in
        '' | ' '* | *' ' | *[!ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789\ ._-]*) return 1 ;;
    esac
    [ "${#1}" -le 32 ]
}

MM_WINDOW_NAME_RULE="a window name is 1 to 32 characters, each a letter, a digit, a space, -, _ or a full stop, and it can't start or end with a space"

cmd_window_name() {
    local name wid wanted sid now auto=0
    [ $# -eq 3 ] || mm_usage_error window-name "usage: window-name <desk> <window id> <name> | --auto"
    name="$1"
    wid="$2"
    wanted="$3"
    case "$wid" in
        @[0-9]*)
            case "${wid#@}" in
                *[!0-9]*) mm_usage_error window-name "the window must be given by its id, such as @3" ;;
            esac
            ;;
        *) mm_usage_error window-name "the window must be given by its id, such as @3" ;;
    esac
    if [ "$wanted" = --auto ]; then
        auto=1
    elif ! mm_valid_window_name "$wanted"; then
        mm_usage_error window-name "$MM_WINDOW_NAME_RULE"
    fi
    # No mm_require_server here: with no desk server there is no window to name, and starting one
    # would only make each desk again as one fresh window.
    sid=""
    if mm_valid_desk_name "$name"; then sid=$(mm_session_id "$name"); fi
    if [ -z "$sid" ]; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log window-name "no such desk: $name"
        return 4
    fi
    if ! mm_session_has_window "$sid" "$wid"; then
        echo "That window has closed." >&2
        mm_log window-name "$name: window $wid has closed"
        return 4
    fi
    # The target is the window by its id inside the desk's session by its id, so a window of another
    # session is never touched. -- keeps a name that starts with - from being read as an option.
    if [ "$auto" = 1 ]; then
        mm_tmux set-option -w -t "$sid:$wid" automatic-rename on >/dev/null 2>&1
        now=$(mm_tmux list-windows -t "$sid:" -F "#{window_id}$TAB#{automatic-rename}" 2>/dev/null |
            awk -F '\t' -v w="$wid" '($1 "") == (w "") { print $2; exit }')
        wanted=1
    else
        mm_tmux rename-window -t "$sid:$wid" -- "$wanted" >/dev/null 2>&1
        now=$(mm_tmux list-windows -t "$sid:" -F "#{window_id}$TAB#{window_name}" 2>/dev/null |
            awk -F '\t' -v w="$wid" '($1 "") == (w "") { sub(/^[^\t]*\t/, ""); print; exit }')
    fi
    # Read back: the window may have closed in the meantime.
    if [ "$now" != "$wanted" ]; then
        if ! mm_session_has_window "$sid" "$wid"; then
            echo "That window has closed." >&2
            mm_log window-name "$name: window $wid has closed"
            return 4
        fi
        echo "macmosh-host: could not name the window" >&2
        mm_log window-name "failed: $name: window $wid"
        return 1
    fi
    if [ "$auto" = 1 ]; then
        mm_log window-name "$name: window $wid named after its program again"
    else
        mm_log window-name "$name: named window $wid"
    fi
    return 0
}

# --- Views: one terminal tab on one window of a desk.
#
# A view is a small tmux session in the same session group as the desk's own session. "Sessions in the
# same group share the same set of windows", and "the current and previous window ... remain independent"
# (man tmux, new-session -t), so each tab keeps its own current window over the desk's windows. A view is
# named "<desk>+<pid of the attach>": the + is not allowed in a desk name, so the status report, desk-closed,
# reopen at start, desk-new, desk-rename, desk-remove, window-new, window-name and attach never take a view for a
# desk. It is tagged with the option @macmosh-view, set to its desk's session id, which a rename keeps,
# and its id is recorded on the server (@macmosh-view-<n>). The name can be changed by hand (tmux's own
# rename, prefix and $, renames the view a tab shows), so the tag keeps a view out of every desk lookup
# (mm_session_id) and the record keeps its closing from counting as a desk's (desk-closed).
# A view ends with its tab (destroy-unattached on, set once the tab is attached), and status sweeps
# a view that never got a tab, or whose desk's own session is gone (mm_sweep_views). Since 0.10.0 a view
# also ends when the window it shows closes (mm_view_rule). Seen with tmux 3.8 on
# a throwaway socket: when a desk's last shell exits, every session of its group closes, and the
# session-closed hook runs for each name.
# A view can carry a label (@macmosh-label, from attach --label): a short word the daily Mac makes up for
# one of its terminal tabs, so that it can match the tab to the view's line in the status report. It is
# set by the view's id with the tag, and only on views; the script never looks a view up by it.
# A view also carries its desk's name (@macmosh-desk, set with the tag, changed by desk-rename), and its
# bar at the bottom of the tab shows that name, not the view's own (mm_view_bar).

# True when $1 is a label: 4 to 32 characters, each a digit or a letter from a to f. The letters are
# listed one by one, because a range such as a-f can take in other letters in some locales.
mm_valid_label() {
    case "$1" in
        '' | *[!0123456789abcdef]*) return 1 ;;
    esac
    [ "${#1}" -ge 4 ] && [ "${#1}" -le 32 ]
}

# Makes a view of a desk showing one window: the given one, a new one made with -d so that no other tab
# moves, or, with neither, the one the desk's own session shows at that moment. Under the desk list's
# lock, which every maker of a desk's session also holds. Sets MM_VIEW_ID and MM_VIEW_WINDOW. Returns 4
# when the desk or the window is gone, 1 when the view can't be made.
mm_open_view() {
    # $1 desk name, $2 window id (@n) or empty, $3 1 for a new window, $4 label or empty
    local name="$1" wid="$2" label="${4:-}" sid grouped group vid check want
    MM_VIEW_ID="" MM_VIEW_WINDOW=""
    if ! mm_lock; then
        echo "macmosh-host: could not lock the desk list" >&2
        mm_log attach "failed: lock"
        return 1
    fi
    sid=$(mm_session_id "$name")
    if [ -z "$sid" ]; then
        mm_release_lock
        echo "macmosh-host: no such desk: $name" >&2
        mm_log attach "no such desk: $name"
        return 4
    fi
    if [ -n "$wid" ] && ! mm_session_has_window "$sid" "$wid"; then
        mm_release_lock
        echo "That window has closed." >&2
        mm_log attach "$name: window $wid has closed"
        return 4
    fi
    grouped=$(mm_session_field "$sid" '#{session_grouped}')
    if [ "$grouped" != 1 ]; then
        # A desk made by a script before 0.7.0 has no group. Its first view makes one, which takes the
        # desk's name, or joins a group that already has that name (seen with tmux 3.8). A group keeps
        # its name for good, so a group with this name belongs to a desk that has been renamed since,
        # and joining it would mix the two desks' windows.
        if mm_tmux list-sessions -F '#{session_group}' 2>/dev/null | grep -qxF -- "$name"; then
            mm_release_lock
            echo "macmosh-host: this desk can open another tab only after the desk server restarts" >&2
            mm_log attach "refused: $name: a group already has its name"
            return 1
        fi
    fi
    # The group is joined through the desk's session id, never its name: a group keeps its first name
    # after a rename, and tmux reads a name as a session's before a group's, so a group's name can
    # stand for another desk (seen with tmux 3.8). Given an id, tmux joins that session's own group.
    # A signal between making the view and tagging it would leave a view no sweep knows, so signals
    # are ignored for those two calls; a tab that closed meanwhile leaves a tagged view to sweep.
    trap '' INT HUP TERM
    vid=$(mm_tmux new-session -d -t "$sid" -s "$name+$$" -P -F '#{session_id}' 2>/dev/null)
    case "$vid" in
        '$'[0-9]*) ;;
        *) vid="" ;;
    esac
    # The tag and the record by the view's own id: a command with no target acts on the session of
    # the pane it is run from (TMUX_PANE), not on the session just made with -d. The record on the
    # server outlives the view, for desk-closed. The desk's name (for the view's bar, see mm_view_bar)
    # and the label, when there is one, go in the same call.
    if [ -n "$vid" ] && [ -n "$label" ]; then
        mm_tmux set-option -t "$vid" @macmosh-view "$sid" \; \
            set-option -s "@macmosh-view-${vid#\$}" "$sid" \; \
            set-option -t "$vid" @macmosh-desk "$name" \; \
            set-option -t "$vid" @macmosh-label "$label" >/dev/null 2>&1
    elif [ -n "$vid" ]; then
        mm_tmux set-option -t "$vid" @macmosh-view "$sid" \; \
            set-option -s "@macmosh-view-${vid#\$}" "$sid" \; \
            set-option -t "$vid" @macmosh-desk "$name" >/dev/null 2>&1
    fi
    trap 'exit 130' INT HUP
    trap 'exit 143' TERM
    group=$(mm_session_field "$sid" '#{session_group}')
    # The tag, the group, the desk's name and the label (when one was given) are read back, so a view
    # that didn't get them is never used.
    if [ -n "$label" ]; then
        check="#{@macmosh-view}$TAB#{session_group}$TAB#{@macmosh-desk}$TAB#{@macmosh-label}"
        want="$sid$TAB$group$TAB$name$TAB$label"
    else
        check="#{@macmosh-view}$TAB#{session_group}$TAB#{@macmosh-desk}" want="$sid$TAB$group$TAB$name"
    fi
    if [ -z "$vid" ] || [ -z "$group" ] || [ "$(mm_session_field "$vid" "$check")" != "$want" ]; then
        if [ -n "$vid" ]; then mm_tmux kill-session -t "$vid" >/dev/null 2>&1; fi
        mm_release_lock
        echo "macmosh-host: could not open a tab on the desk $name" >&2
        mm_log attach "failed: no view for $name"
        return 1
    fi
    mm_view_bar "$vid"
    if [ "$3" = 1 ]; then
        # The desk's own session is the target, so the window starts in the desk's folder as window-new's do.
        wid=$(mm_tmux new-window -d -P -F '#{window_id}' -t "$sid:" 2>/dev/null)
        case "$wid" in
            @[0-9]*) ;;
            *)
                mm_tmux kill-session -t "$vid" >/dev/null 2>&1
                mm_release_lock
                echo "macmosh-host: could not add a window" >&2
                mm_log attach "failed: no window for $name"
                return 1
                ;;
        esac
    elif [ -z "$wid" ]; then
        # Neither option: the window the desk's own session shows now, read as late as possible. A new
        # view starts on the group's lowest window (seen with tmux 3.8), so it is moved there below.
        wid=$(mm_session_field "$sid" '#{window_id}')
        case "$wid" in
            @[0-9]*) ;;
            *)
                mm_tmux kill-session -t "$vid" >/dev/null 2>&1
                mm_release_lock
                echo "macmosh-host: no such desk: $name" >&2
                mm_log attach "no such desk: $name"
                return 4
                ;;
        esac
    fi
    if ! mm_tmux select-window -t "$vid:$wid" >/dev/null 2>&1; then
        mm_tmux kill-session -t "$vid" >/dev/null 2>&1
        mm_release_lock
        echo "That window has closed." >&2
        mm_log attach "$name: window $wid has closed"
        return 4
    fi
    mm_view_rule "$vid" "$sid"
    mm_release_lock
    MM_VIEW_ID="$vid"
    MM_VIEW_WINDOW="$wid"
    return 0
}

# The status-left text with each place it names the session (#S, #{session_name}) reading the view's
# @macmosh-desk instead, or nothing (and false) when it names the session nowhere. ## is tmux's escaped
# #, so ##S is text and stays as it is. Every other character stays as it is.
mm_bar_with_desk() {
    local rest="$1" out="" found=1 hash='#' long='#{session_name}'
    while :; do
        case "$rest" in
            *"$hash"*) ;;
            *) break ;;
        esac
        out="$out${rest%%"$hash"*}"
        rest="$hash${rest#*"$hash"}"
        case "$rest" in
            "$hash$hash"*)
                out="$out##"
                rest="${rest#"$hash$hash"}"
                ;;
            "${hash}S"*)
                out="$out#{@macmosh-desk}"
                rest="${rest#"$hash"S}"
                found=0
                ;;
            "$long"*)
                out="$out#{@macmosh-desk}"
                rest="${rest#"$long"}"
                found=0
                ;;
            *)
                out="$out#"
                rest="${rest#"$hash"}"
                ;;
        esac
    done
    [ "$found" = 0 ] || return 1
    printf '%s' "$out$rest"
}

# Gives the view with this id a bar (status-left) of its own that shows its desk's name where the
# server's bar shows the session's, which for a view would be "<desk>+<number>". tmux 3.8's own bar is
# "[#{session_name}] ", so a view's reads "[<desk>] " as a plain tab's does; a bar the person set in his
# tmux settings keeps everything but the name, and one that names the session nowhere is left alone.
# The option is set on the view only: a session's own options stay with it, also in a group (man tmux,
# new-session -t; ViewBarTests). The bar reads the name through #{@macmosh-desk}, so desk-rename only has
# to change that option (mm_name_views). The name is never pasted into the bar, and even read through
# the option it could do no harm in a format or in a #() shell command: mm_valid_desk_name lets it hold
# only letters, digits, - and _.
# tmux reads a trailing ";" on an argument as a command separator (man tmux, COMMANDS), so the bar
# is read back, and one that didn't come through as written is taken off again. A bar is only for
# show, so nothing here makes the tab fail.
mm_view_bar() {
    local bar
    bar=$(mm_bar_with_desk "$(mm_tmux show-options -gv status-left 2>/dev/null)") || return 0
    mm_tmux set-option -t "$1" status-left "$bar" >/dev/null 2>&1
    if [ "$(mm_tmux show-options -t "$1" -v status-left 2>/dev/null)" != "$bar" ]; then
        mm_tmux set-option -u -t "$1" status-left >/dev/null 2>&1
    fi
    return 0
}

# --- A view ends with the window it shows (issue 139, 0.10.0).
#
# tmux moves a session to another window of its group when the window it shows closes, so a tab on one
# window whose window closed went on to show a window another tab already showed. Now the view ends,
# and its tab closes with it. Seen with tmux 3.8 on a throwaway socket (WindowCloseHookTests): each
# session of the group that showed the closed window gets session-window-changed, and by the time the
# hook runs the window is gone from that session's windows; a session that showed another window gets
# none; the person switching windows runs it for that session only, and the window left is still one
# of its windows; the group's last window closing runs it for no session (every session closes, as
# before).
# So the view remembers the window it shows (the option @macmosh-window) and has one hook of its own,
# both set by the view's id: when its current window changes, it ends if the window it remembers is no
# longer one of its windows, and otherwise remembers the new one. That follows the person when he
# switches windows inside the tab. The hook decides with tmux's formats alone (if-shell -F runs no
# shell), so a window switch starts no process.
# It ends the view by detaching its tab's client, never with kill-session: a session that a command
# run from a hook kills runs no session-closed hook (seen with tmux 3.8), so desk-closed would never
# clear the view's record. Detached, the client exits, the view has no client left, and its own
# destroy-unattached ends it after the hook, exactly as when the tab closes: session-closed runs and
# desk-closed ignores it by its record, as for any view. Ending views closes no other window only
# while the desk's own session is there, since it holds every window of the desk, so the hook acts only
# then (a loop over the server's sessions finds it by its id, which tmux never gives to another
# session and which desk-rename keeps). Views left without it (the desk's session killed by hand) hold
# the desk's windows between them, and keep today's behaviour; a guard on the group's size missed two
# such views on one window, as each read a group of two. A view with no tab is left to the sweep in
# status. The formats were tried with tmux 3.8 only.
# tmux's own swap-window (also bound to a Ctrl-click in the status bar) changes the window a grouped
# session shows without running session-window-changed for it (WindowCloseHookTests), so the window a
# view remembers can fall behind. A second hook of the view's own, on window-unlinked (which every
# session of the group gets when a window closes, each after its own session-window-changed), takes
# up the window the view shows when the window it remembers leaves the view. That covers a window
# closed by its shell exiting. One case is known to remain (found by the second check of pull request
# 141, left as it is, issue #142): after a swap, a window closed by a tmux command (kill-window, kill-pane) can
# leave another tab's memory behind, and that tab then closes on its next window switch although its
# window is open. Nothing is lost; the menu opens the tab again. It acts only when the hook is run for the view itself
# (hook_session): after a kill-window, tmux 3.8 was seen to run a session's window-unlinked hook for
# another session of the group too, before that session's own session-window-changed. A view the swap
# moved onto a window that then closes still moves on, as before 0.10.0.
# Limits: a hook of the view's own takes the place of the global hook of the same name for that view
# (seen with tmux 3.8), so a session-window-changed or window-unlinked hook in the person's own tmux
# settings doesn't run for a tab on one window. A view made by a script before 0.10.0 has no such
# hooks, and keeps today's behaviour until its tab closes. Errors are ignored: a view without the rule
# behaves as before.
mm_view_rule() {
    local vid="$1" sid="$2" gone
    case "$sid" in
        '$'[0-9]*) ;;
        *) return 0 ;;
    esac
    # shellcheck disable=SC2016  # the #{...} parts are tmux formats, expanded when the hook runs
    gone='#{&&:#{@macmosh-window},#{&&:#{S:#{?#{==:#{session_id},'"$sid"'},1,}},#{!:#{W:#{?#{==:#{window_id},#{@macmosh-window}},1,}}}}}'
    mm_tmux set-option -F -t "$vid" @macmosh-window '#{window_id}' \; \
        set-hook -t "$vid" 'session-window-changed[1089]' \
        "if-shell -F -t '$vid' '$gone' { detach-client -s '$vid' } { set-option -F -t '$vid' @macmosh-window '#{window_id}' }" \; \
        set-hook -t "$vid" 'window-unlinked[1089]' \
        "if-shell -F -t '$vid' '#{&&:#{==:#{hook_session},$vid},#{==:#{hook_window},#{@macmosh-window}}}' { set-option -F -t '$vid' @macmosh-window '#{window_id}' }" \
        >/dev/null 2>&1
    return 0
}

# The ids of the views of the desk whose session has this id, one per line.
mm_view_ids() {
    mm_tmux list-sessions -F "#{session_id}$TAB#{@macmosh-view}" 2>/dev/null |
        awk -F '\t' -v d="$1" '($2 "") == (d "") { print $1 }'
}

# Kills every view of the desk whose session has this id, each by its own id.
mm_kill_views() {
    local vid
    for vid in $(mm_view_ids "$1"); do
        mm_tmux kill-session -t "$vid" >/dev/null 2>&1
    done
    return 0
}

# Sets the desk's name ($2) on every view of the desk whose session has id $1, each by its own id, so
# their bars show it (see mm_view_bar).
mm_name_views() {
    local vid
    for vid in $(mm_view_ids "$1"); do
        mm_tmux set-option -t "$vid" @macmosh-desk "$2" >/dev/null 2>&1
    done
    return 0
}

MM_LABEL_RULE="--label needs a word of 4 to 32 characters, each a digit or a letter from a to f"

# attach --label gives the tab's view a label (see mm_open_view). With --window or --new-window it goes
# on that view; with neither, the tab gets a view on the window the desk shows now, not the desk's own
# session. A dry run checks the label as it checks the window, and makes no view.
cmd_attach() {
    local name="" cc=0 dry=0 npos=0 line sid window="" newwin=0 vid="" code label="" labelled=0
    while [ $# -gt 0 ]; do
        case "$1" in
            --cc) cc=1 ;;
            --dry-run) dry=1 ;;
            --window)
                [ $# -ge 2 ] || mm_usage_error attach "--window needs a window id, such as @3"
                window="$2"
                shift
                ;;
            --new-window) newwin=1 ;;
            --label)
                [ $# -ge 2 ] || mm_usage_error attach "$MM_LABEL_RULE"
                label="$2"
                labelled=1
                shift
                ;;
            --*) mm_usage_error attach "unknown option $1" ;;
            *)
                npos=$((npos + 1))
                [ "$npos" -le 1 ] || mm_usage_error attach "too many arguments"
                name="$1"
                ;;
        esac
        shift
    done
    [ "$npos" -eq 1 ] || mm_usage_error attach "usage: attach [--cc] [--window @<id> | --new-window] [--label <word>] [--dry-run] <desk>"
    if [ "$labelled" = 1 ] && ! mm_valid_label "$label"; then
        mm_usage_error attach "$MM_LABEL_RULE"
    fi
    if [ "$labelled" = 1 ] && [ "$cc" = 1 ]; then
        mm_usage_error attach "--cc can't be used with --label"
    fi
    case "$window" in
        '') ;;
        @[0-9]*)
            case "${window#@}" in
                *[!0-9]*) mm_usage_error attach "--window needs a window id, such as @3" ;;
            esac
            ;;
        *) mm_usage_error attach "--window needs a window id, such as @3" ;;
    esac
    if [ -n "$window" ] && [ "$newwin" = 1 ]; then
        mm_usage_error attach "--window and --new-window can't be used together"
    fi
    # Tabs mode shows every window as a tab already, and needs no views.
    if [ "$cc" = 1 ] && { [ -n "$window" ] || [ "$newwin" = 1 ]; }; then
        mm_usage_error attach "--cc can't be used with --window or --new-window"
    fi

    if ! mm_valid_desk_name "$name"; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log attach "no such desk"
        return 4
    fi
    mm_require_server attach
    mm_set_hook

    # A closed desk that still has its definition (a permanent desk, or one that ended with the
    # server) is made again from it, under the desk list's lock, so the exit path can't remove the
    # definition between the read and the new session.
    if ! mm_session_exists "$name"; then
        if ! mm_lock; then
            echo "macmosh-host: could not lock the desk list" >&2
            mm_log attach "failed: lock"
            return 1
        fi
        line=$(mm_def_line "$name")
        if [ -z "$line" ]; then
            mm_release_lock
            echo "macmosh-host: no such desk: $name" >&2
            mm_log attach "no such desk: $name"
            return 4
        fi
        mm_read_def "$line"
        if ! mm_session_exists "$name" && ! mm_create_session "$name" "$d_folder" "$d_command" "$d_keep"; then
            mm_release_lock
            echo "macmosh-host: could not open the desk $name" >&2
            mm_log attach "failed: $name could not be created"
            return 1
        fi
        mm_release_lock
    fi

    if [ "$dry" = 1 ]; then
        # A dry run checks the window it was given and makes nothing: no view, no window.
        sid=$(mm_session_id "$name")
        if [ -n "$window" ] && { [ -z "$sid" ] || ! mm_session_has_window "$sid" "$window"; }; then
            echo "That window has closed." >&2
            mm_log attach "dry run $name: window $window has closed"
            return 4
        fi
        echo ok
        mm_log attach "dry run $name"
        return 0
    fi
    if [ -n "$window" ] || [ "$newwin" = 1 ] || [ "$labelled" = 1 ]; then
        code=0
        mm_open_view "$name" "$window" "$newwin" "$label" || code=$?
        [ "$code" = 0 ] || return "$code"
        vid="$MM_VIEW_ID"
        if [ "$labelled" = 1 ]; then label=", label $label"; fi
        if [ "$newwin" = 1 ]; then
            mm_log attach "$name (new window $MM_VIEW_WINDOW$label)"
        else
            mm_log attach "$name (window $MM_VIEW_WINDOW$label)"
        fi
    else
        # By id, looked up last: a desk that closed since the check above is no desk to attach to.
        sid=$(mm_session_id "$name")
        if [ -z "$sid" ]; then
            echo "macmosh-host: no such desk: $name" >&2
            mm_log attach "no such desk: $name"
            return 4
        fi
        mm_log attach "$name"
    fi
    # The terminal may itself be inside another tmux; the desk server is a separate one.
    unset TMUX
    if [ "$cc" = 1 ]; then
        exec tmux -L "$MACMOSH_SOCKET" -CC attach-session -t "$sid"
    fi
    if [ -n "$vid" ]; then
        # The view goes when its tab goes: "on" destroys the session once it has no client. While the
        # desk's own session is there, that closes no window; once it is gone (killed by hand, or by
        # the script before 0.7.0, which knows nothing of views), the last view takes the windows with
        # it. keep-last would keep a view that is alone in its group, with its shells running, until a
        # status check of 0.7.0 swept it. It is set after the attach, in the same command list, because
        # set on a view that has no client yet it destroys the view at once (seen with tmux 3.8). If the
        # attach fails, the option is never set, and status sweeps the view a minute later.
        set -- attach-session -t "$vid" \; set-option -t "$vid" destroy-unattached on
    else
        set -- attach-session -t "$sid"
    fi
    exec tmux -L "$MACMOSH_SOCKET" "$@"
}

# Runs the desk's startup command, and again each time it ends. It runs inside the desk's own shell
# (the desk types "<this script> keep <desk>"), so it reads the definition and starts nothing else:
# it never needs the desk server and never starts one.
# The pause starts at MACMOSH_KEEP_PAUSE seconds (default 5) and doubles, up to 60, while the command
# keeps ending within 10 seconds. A run of a minute or more sets it back to the start. A run in
# between leaves it as it is.
cmd_keep() {
    local name line folder command start pause next began took code stopped=0 cur locked=0
    [ $# -eq 1 ] || mm_usage_error keep "usage: keep <desk>"
    name="$1"
    line=""
    # The desk is the session this runs in, when it runs in one: the shell may read the typed
    # "keep <desk>" only after a rename. The answer counts only when it comes from the server this
    # shell runs in, whose socket $TMUX names.
    # The name and the line are read under the lock, which desk-rename holds while it changes both,
    # so they are both old or both new. Without the lock they are read as they are.
    if mm_lock; then locked=1; fi
    # A pane that a view also shows may be reported as the view's (seen with tmux 3.8); the view's tag
    # holds its desk's session id, and that session's name is the desk's.
    if [ -n "${TMUX:-}" ] && [ -n "${TMUX_PANE:-}" ]; then
        cur=$(mm_tmux display-message -p -t "$TMUX_PANE" "#{socket_path}$TAB#{@macmosh-view}$TAB#{session_name}" 2>/dev/null)
        if [ "${cur%%"$TAB"*}" = "${TMUX%%,*}" ]; then cur="${cur#*"$TAB"}"; else cur=""; fi
        case "$cur" in
            '$'[0-9]*"$TAB"*) cur=$(mm_session_field "${cur%%"$TAB"*}" '#{session_name}') ;;
            *) cur="${cur#*"$TAB"}" ;;
        esac
        if [ -n "$cur" ] && mm_valid_desk_name "$cur"; then
            line=$(mm_def_line "$cur")
            if [ -n "$line" ]; then name="$cur"; fi
        fi
    fi
    if [ -z "$line" ] && mm_valid_desk_name "$name"; then
        line=$(mm_def_line "$name")
    fi
    if [ "$locked" = 1 ]; then mm_release_lock; fi
    if [ -z "$line" ]; then
        echo "macmosh-host: no such desk: $name" >&2
        mm_log keep "no such desk: $name"
        return 4
    fi
    mm_read_def "$line"
    folder="$d_folder"
    command="$d_command"
    if [ -z "$command" ]; then
        echo "There is nothing to keep running in the desk $name: it has no startup command."
        mm_log keep "$name: no command"
        return 0
    fi
    start="${MACMOSH_KEEP_PAUSE:-5}"
    case "$start" in
        '' | *[!0-9]*) start=5 ;;
    esac
    [ "$start" -ge 1 ] || start=5
    if [ -d "$folder" ]; then cd "$folder" || true; fi
    mm_log keep "$name: started"

    pause="$start"
    while :; do
        began=$(date +%s)
        # Ctrl-C goes to the command. This script only has to live through it.
        trap ':' INT
        "${SHELL:-/bin/zsh}" -lc "$command"
        code=$?
        trap - INT
        took=$(($(date +%s) - began))

        printf '%s ended (exit %s). Starting it again in %s seconds. Press Ctrl-C to stop.\n' "$command" "$code" "$pause"
        stopped=0
        trap 'stopped=1' INT
        sleep "$pause"
        trap - INT
        if [ "$stopped" = 1 ]; then
            echo
            mm_log keep "$name: stopped"
            return 0
        fi

        if [ "$took" -lt 10 ]; then
            next=$((pause * 2))
            [ "$next" -le 60 ] || next=60
            [ "$next" -ge "$pause" ] || next="$pause"
            pause="$next"
        elif [ "$took" -ge 60 ]; then
            pause="$start"
        fi
    done
}

cmd_folders() {
    local folder entry name
    [ $# -eq 1 ] || mm_usage_error folders "usage: folders <folder>"
    folder=$(mm_expand_tilde "$1")
    if [ -z "$folder" ] || [ ! -d "$folder" ]; then
        echo "macmosh-host: no such folder: $1" >&2
        mm_log folders "refused: no such folder"
        return 6
    fi
    # The glob skips hidden folders. A name with a new line in it would break the one-per-line list.
    for entry in "${folder%/}"/*/; do
        [ -d "$entry" ] || continue
        name="${entry%/}"
        name="${name##*/}"
        case "$name" in
            *$'\n'*) continue ;;
        esac
        printf '%s\n' "$name"
    done | LC_ALL=C sort
    mm_log folders "ok"
    return 0
}

# ---------------------------------------------------------------- login agent, restart, removal

# Text safe to put inside a plist <string>.
mm_xml_escape() {
    printf '%s' "$1" | sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g'
}

cmd_install_agent() {
    local script agent_dir plist tmp uid status=0
    script="$MACMOSH_HOME/macmosh-host"
    # The path goes inside double quotes in a zsh command line: refuse what would break out of them.
    case "$script" in
        *'"'* | *'$'* | *'`'* | *\\*)
            echo "macmosh-host: the script's path has a character the login agent can't carry" >&2
            mm_log install-agent "refused: odd path"
            return 1
            ;;
    esac
    uid=$(id -u)
    agent_dir="$HOME/Library/LaunchAgents"
    plist="$agent_dir/$AGENT_LABEL.plist"
    tmp="$plist.$$.tmp"
    if ! mkdir -p "$agent_dir"; then
        echo "macmosh-host: cannot create $agent_dir" >&2
        mm_log install-agent "failed: no folder"
        return 1
    fi
    if ! {
        cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key>
    <string>$AGENT_LABEL</string>
    <key>ProgramArguments</key>
    <array>
        <string>/bin/zsh</string>
        <string>-lc</string>
        <string>exec "$(mm_xml_escape "$script")" start</string>
    </array>
    <key>RunAtLoad</key>
    <true/>
    <key>LimitLoadToSessionType</key>
    <string>Aqua</string>
</dict>
</plist>
EOF
    } > "$tmp" || ! mv "$tmp" "$plist"; then
        rm -f "$tmp"
        echo "macmosh-host: cannot write $plist" >&2
        mm_log install-agent "failed: cannot write"
        return 1
    fi
    # Unload an older copy first; it is fine if there is none.
    launchctl bootout "gui/$uid/$AGENT_LABEL" >/dev/null 2>&1
    launchctl bootstrap "gui/$uid" "$plist" || status=$?
    mm_log install-agent "exit $status"
    return "$status"
}

cmd_restart_server() {
    local yes=0 arg n=0
    for arg in "$@"; do
        case "$arg" in
            --yes) yes=1 ;;
            *) mm_usage_error restart-server "usage: restart-server --yes" ;;
        esac
    done
    [ "$yes" = 1 ] || mm_usage_error restart-server "restart-server closes every desk: add --yes to confirm"

    # Check first: with nobody at the screen the server could not come back, so close nothing.
    if [ -z "$(mm_console_user)" ]; then
        echo "Nobody is logged in at this Mac's screen, so desks can't start. Log in first." >&2
        mm_log restart-server "nobody logged in"
        return 3
    fi
    if mm_server_up; then
        mm_tmux kill-server >/dev/null 2>&1
        while mm_server_up && [ "$n" -lt 20 ]; do
            sleep 0.25
            n=$((n + 1))
        done
        if mm_server_up; then
            echo "The desk server didn't stop." >&2
            mm_log restart-server "server did not stop"
            return 5
        fi
    fi
    mm_require_server restart-server
    mm_log restart-server "ok"
    return 0
}

# Removes every line of authorized_keys that has the key as a whole field. The file is rewritten
# through a temporary file in its own folder and mv, keeps its mode, and is left alone when no
# line matches or when anything fails.
mm_remove_authorized_key() {
    local key="$1" file="$HOME/.ssh/authorized_keys" dir tmp mode removed
    [ -f "$file" ] || return 0
    dir=$(dirname "$file")
    tmp=$(mktemp "$dir/authorized_keys.XXXXXX") || return 1
    removed=$(LC_ALL=C awk -v key="$key" -v out="$tmp" '
        { hit = 0; for (i = 1; i <= NF; i++) if ($i == key) hit = 1 }
        hit { n++; next }
        { print > out }
        END { close(out); print n + 0 }
    ' "$file") || {
        rm -f "$tmp"
        return 1
    }
    if [ "$removed" = 0 ]; then
        rm -f "$tmp"
        return 0
    fi
    mode=$(/usr/bin/stat -f %Lp "$file" 2>/dev/null)
    case "$mode" in
        '' | *[!0-7]*) mode=600 ;;
    esac
    if ! chmod "$mode" "$tmp" || ! mv "$tmp" "$file"; then
        rm -f "$tmp"
        return 1
    fi
    return 0
}

cmd_uninstall() {
    local key="" have_key=0
    while [ $# -gt 0 ]; do
        case "$1" in
            --key)
                [ $# -ge 2 ] || mm_usage_error uninstall "--key needs a value"
                key="$2"
                have_key=1
                shift
                ;;
            *) mm_usage_error uninstall "usage: uninstall --key <base64 key>" ;;
        esac
        shift
    done
    if [ "$have_key" = 0 ] || [ "${#key}" -lt 60 ]; then
        echo "macmosh-host: uninstall needs --key with MacMosh's whole public key (at least 60 characters)" >&2
        return 2
    fi
    case "$key" in
        *[!A-Za-z0-9+/=]*)
            echo "macmosh-host: the key isn't base64" >&2
            return 2
            ;;
    esac
    # Never delete a folder that could hold more than MacMosh's own files.
    case "$MACMOSH_HOME" in
        '' | / | "$HOME" | "$HOME/")
            echo "macmosh-host: refusing to remove $MACMOSH_HOME" >&2
            return 1
            ;;
    esac

    # The key first: if that fails, nothing else has been touched.
    if ! mm_remove_authorized_key "$key"; then
        echo "macmosh-host: could not update ~/.ssh/authorized_keys; nothing was removed" >&2
        return 1
    fi
    launchctl bootout "gui/$(id -u)/$AGENT_LABEL" >/dev/null 2>&1
    rm -f "$HOME/Library/LaunchAgents/$AGENT_LABEL.plist"
    # The desk server and open desks keep running. The log lives in the folder being emptied,
    # so this subcommand logs nothing: a log line would bring the folder back.
    # Remove only the names MacMosh makes there; a folder named by an environment variable
    # may hold other things.
    rm -f "$MACMOSH_HOME/macmosh-host" "$MACMOSH_HOME/macmosh-host.new" \
        "$MACMOSH_HOME/tmux.conf" "$MACMOSH_HOME/$DESKS_FILE_NAME" "$MACMOSH_HOME/host.log" \
        "$MACMOSH_HOME/$DESKS_FILE_NAME".*.tmp "$MACMOSH_HOME/host.log".*.tmp
    rmdir "$MACMOSH_HOME/lock" 2>/dev/null
    if [ -e "$MACMOSH_HOME" ] && ! rmdir "$MACMOSH_HOME" 2>/dev/null; then
        echo "macmosh-host: kept $MACMOSH_HOME because it holds files MacMosh didn't put there" >&2
    fi
    return 0
}

# ---------------------------------------------------------------- status

# A value from the "AC Power:" section of `pmset -g custom`: the first whole number after the name.
mm_power_value() {
    # $1 setting name, $2 the pmset text
    local v
    v=$(printf '%s\n' "$2" | awk -v key="$1" '
        /^AC Power:/ { ac = 1; next }
        /^[^ \t]/ { ac = 0 }
        ac && $1 == key {
            for (i = 2; i <= NF; i++) if ($i ~ /^[0-9]+$/) { print $i; exit }
        }')
    if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "-"; fi
}

# The lid-closed setting (`pmset -a disablesleep`). `pmset -g custom` never lists it; plain `pmset -g`
# has a line " SleepDisabled", two tabs and the number once it has been turned on (seen on macOS 27.3).
# Prints that number, or "-" when the line is absent or has no number.
mm_lid_value() {
    # $1 the text of `pmset -g`
    local v
    v=$(printf '%s\n' "$1" | awk '
        $1 == "SleepDisabled" && $2 ~ /^[0-9]+$/ { print $2; exit }')
    if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "-"; fi
}

# 255.255.255.0 -> 24. Prints nothing for anything that is not a dotted mask.
mm_mask_to_prefix() {
    local mask="$1" a b c d bits=0 octet
    case "$mask" in
        *[!0-9.]* | '') return 0 ;;
    esac
    IFS=. read -r a b c d <<EOF
$mask
EOF
    for octet in "$a" "$b" "$c" "$d"; do
        case "$octet" in
            '' | *[!0-9]*) return 0 ;;
        esac
        [ "$octet" -le 255 ] || return 0
        while [ "$octet" -gt 0 ]; do
            bits=$((bits + (octet & 1)))
            octet=$((octet >> 1))
        done
    done
    printf '%s' "$bits"
}

# A hex mask such as 0xffffff00 -> 24.
mm_hexmask_to_prefix() {
    local hex="${1#0x}" value bits=0
    case "$hex" in
        '' | *[!0-9a-fA-F]*) return 0 ;;
    esac
    value=$((16#$hex))
    while [ "$value" -gt 0 ]; do
        bits=$((bits + (value & 1)))
        value=$((value >> 1))
    done
    printf '%s' "$bits"
}

# True for 100.64.0.0/10, the range Tailscale uses.
mm_is_tailscale_address() {
    local a b rest
    IFS=. read -r a b rest <<EOF
$1
EOF
    [ "$a" = 100 ] || return 1
    case "$b" in
        '' | *[!0-9]*) return 1 ;;
    esac
    [ "$b" -ge 64 ] && [ "$b" -le 127 ]
}

mm_home_record() {
    local iface addr="" n mask prefix="" localname="" line

    iface=$(route -n get default 2>/dev/null | awk '/interface:/ { print $2; exit }')
    if [ -n "$iface" ]; then
        addr=$(ipconfig getifaddr "$iface" 2>/dev/null)
    fi
    # A tunnel (or an address in Tailscale's range) is not the home address: use the first en0..en9 that has one.
    case "$iface" in
        utun*) addr="" ;;
    esac
    if [ -n "$addr" ] && mm_is_tailscale_address "$addr"; then
        addr=""
    fi
    if [ -z "$addr" ] && [ -n "$iface" ]; then
        n=0
        while [ "$n" -le 9 ]; do
            addr=$(ipconfig getifaddr "en$n" 2>/dev/null)
            if [ -n "$addr" ]; then
                iface="en$n"
                break
            fi
            n=$((n + 1))
        done
    fi

    if [ -n "$addr" ]; then
        mask=$(ipconfig getoption "$iface" subnet_mask 2>/dev/null)
        prefix=$(mm_mask_to_prefix "$mask")
        if [ -z "$prefix" ]; then
            # A fixed address has no DHCP option: read the mask from ifconfig instead.
            line=$(ifconfig "$iface" 2>/dev/null | awk '/^[ \t]*inet / { for (i = 1; i < NF; i++) if ($i == "netmask") { print $(i + 1); exit } }')
            prefix=$(mm_hexmask_to_prefix "$line")
        fi
    fi

    localname=$(scutil --get LocalHostName 2>/dev/null)
    if [ -n "$localname" ]; then localname="$localname.local"; fi

    printf 'home\t%s\t%s\t%s\n' "$(mm_clean "$addr")" "$prefix" "$(mm_clean "$localname")"
}

mm_battery_record() {
    local text present=absent source=ac pct="-" first
    text=$(pmset -g batt 2>/dev/null)
    first=$(printf '%s\n' "$text" | head -n 1)
    case "$first" in
        *"'Battery Power'"*) source=battery ;;
    esac
    case "$text" in
        *InternalBattery*)
            present=present
            pct=$(printf '%s\n' "$text" | sed -n 's/.*[^0-9]\([0-9][0-9]*\)%.*/\1/p' | head -n 1)
            [ -n "$pct" ] || pct="-"
            ;;
    esac
    printf 'battery\t%s\t%s\t%s\n' "$present" "$source" "$pct"
}

mm_tool_record() {
    # $1 name, $2 path or empty, $3 version or empty
    printf 'tool\t%s\t%s\t%s\n' "$1" "${2:--}" "${3:--}"
}

mm_tool_records() {
    local path version

    path=$(command -v brew 2>/dev/null)
    mm_tool_record brew "$path" ""

    path=$(command -v mosh-server 2>/dev/null)
    version=""
    if [ -n "$path" ]; then
        version=$(mosh-server --version 2>&1 | sed -n 's/.*(mosh \([^)]*\)).*/\1/p' | head -n 1)
    fi
    mm_tool_record mosh-server "$path" "$version"

    path=$(command -v tmux 2>/dev/null)
    version=""
    if [ -n "$path" ]; then
        version=$(tmux -V 2>/dev/null | awk '{ print $2; exit }')
    fi
    mm_tool_record tmux "$path" "$version"
}

# The windows of one desk. A window name can hold odd characters; a line that does not start with
# "index|" is the rest of the previous name. $1 is the desk's name, $2 its session id.
mm_window_records() {
    local desk="$1" sid="$2" text
    text=$(mm_tmux list-windows -t "$sid:" -F '#{window_index}|#{window_name}' 2>/dev/null)
    printf '%s\n' "$text" | {
        local line prev=""
        while IFS= read -r line; do
            case "$line" in
                [0-9]*"|"*)
                    if [ -n "$prev" ]; then
                        printf 'window\t%s\t%s\t%s\n' "$desk" "${prev%%|*}" "$(mm_clean "${prev#*|}")"
                    fi
                    prev="$line"
                    ;;
                *) prev="$prev $line" ;;
            esac
        done
        if [ -n "$prev" ]; then
            printf 'window\t%s\t%s\t%s\n' "$desk" "${prev%%|*}" "$(mm_clean "${prev#*|}")"
        fi
    }
}

# Which windows of one desk a tab shows, after its window records: one "windowinfo" line per window
# (desk, index, window id, 1 when the desk's own session shows it, the number of tabs showing it) and
# one "view" line per view (desk, the view's name, the window it shows now, its tabs, its label or
# nothing). window_active_clients counts the tabs of every session in the group (seen with tmux 3.8).
# An older app skips both records.
# $1 is the desk's name, $2 its session id, $3 the list of every session (id, tag, tabs, window, label,
# name).
mm_window_info_records() {
    local desk="$1" sid="$2" index wid active tabs tag view label
    mm_tmux list-windows -t "$sid:" -F '#{window_index}|#{window_id}|#{window_active}|#{window_active_clients}' 2>/dev/null |
        while IFS='|' read -r index wid active tabs; do
            case "$index$active$tabs" in
                '' | *[!0-9]*) continue ;;
            esac
            printf 'windowinfo\t%s\t%s\t%s\t%s\t%s\n' "$desk" "$index" "$wid" "$active" "$tabs"
        done
    printf '%s\n' "$3" | while IFS='|' read -r _ tag tabs wid label view; do
        [ -n "$tag" ] && [ "$tag" = "$sid" ] || continue
        case "$tabs" in
            '' | *[!0-9]*) continue ;;
        esac
        mm_valid_label "$label" || label=""
        printf 'view\t%s\t%s\t%s\t%s\t%s\n' "$desk" "$(mm_clean "$view")" "$wid" "$tabs" "$label"
    done
}

mm_desk_records() {
    local text sessions line name windows attached sid tag
    mm_server_up || return 0
    # Format: id|tag|windows|attached|name. A name that breaks the naming rule is left out, and so is a
    # view (a session tagged @macmosh-view). The windows are listed by the session's id, never by "=name"
    # (see mm_session_id). A desk's tabs are those of every session in its group, its views' included.
    text=$(mm_tmux list-sessions -F '#{session_id}|#{@macmosh-view}|#{session_windows}|#{?session_grouped,#{session_group_attached},#{session_attached}}|#{session_name}' 2>/dev/null)
    # A view's label is given only when it is all digits and letters from a to f, so a label set by hand
    # can't hold the | that separates the fields; mm_window_info_records checks its length.
    sessions=$(mm_tmux list-sessions -F '#{session_id}|#{@macmosh-view}|#{session_attached}|#{window_id}|#{?#{m/r:^[0-9a-f]+$,#{@macmosh-label}},#{@macmosh-label},}|#{session_name}' 2>/dev/null)
    printf '%s\n' "$text" | while IFS= read -r line; do
        sid="${line%%|*}"
        line="${line#*|}"
        case "$sid" in
            '$'[0-9]*) ;;
            *) continue ;;
        esac
        tag="${line%%|*}"
        line="${line#*|}"
        windows="${line%%|*}"
        line="${line#*|}"
        attached="${line%%|*}"
        name="${line#*|}"
        [ -z "$tag" ] || continue
        mm_valid_desk_name "$name" || continue
        case "$windows$attached" in
            '' | *[!0-9]*) continue ;;
        esac
        printf 'desk\t%s\t%s\t%s\n' "$name" "$windows" "$attached"
        mm_window_records "$name" "$sid"
        mm_window_info_records "$name" "$sid" "$sessions"
    done
}

# Removes the views that never got a tab, or kept none: tagged @macmosh-view, no client, and older than
# MACMOSH_VIEW_SWEEP_AGE seconds (a minute by default). A tab attaches to its view within a moment of
# making it and never later, so an old view with no client is never one a tab is reaching for.
# Which of two cases it is decides what goes with it, and is read from the desk's own session, which
# the sweep never kills:
# - the desk's session is there, in the view's group: plain kill-session closes only windows no other
#   session shows, so the desk keeps every window;
# - the desk's session is gone (killed by hand, which closed every window before views existed): the
#   view holds the desk's windows, out of the menu, and they go with it, as they would have gone then.
# A view whose tag names a session in another group is left alone.
MM_VIEW_SWEEP_AGE="${MACMOSH_VIEW_SWEEP_AGE:-60}"
case "$MM_VIEW_SWEEP_AGE" in
    '' | *[!0-9]*) MM_VIEW_SWEEP_AGE=60 ;;
esac

mm_sweep_views() {
    local now text vid tag attached created group desk n=0
    now=$(date +%s)
    text=$(mm_tmux list-sessions -F '#{session_id}|#{@macmosh-view}|#{session_attached}|#{session_created}|#{session_group}' 2>/dev/null)
    while IFS='|' read -r vid tag attached created group; do
        [ -n "$tag" ] || continue
        case "$vid" in
            '$'[0-9]*) ;;
            *) continue ;;
        esac
        case "$attached$created" in
            '' | *[!0-9]*) continue ;;
        esac
        [ "$attached" = 0 ] && [ $((now - created)) -gt "$MM_VIEW_SWEEP_AGE" ] || continue
        # "x" and the desk's group, or nothing when the desk's session is gone.
        desk=$(mm_session_field "$tag" 'x#{session_group}')
        [ -z "$desk" ] || { [ -n "$group" ] && [ "$desk" = "x$group" ]; } || continue
        if mm_tmux kill-session -t "$vid" >/dev/null 2>&1; then n=$((n + 1)); fi
    done <<EOF
$text
EOF
    if [ "$n" = 1 ]; then
        mm_log status "removed 1 view with no tab"
    elif [ "$n" -gt 1 ]; then
        mm_log status "removed $n views with no tab"
    fi
    return 0
}

# Every definition in the newest form, whatever form its line in desks.tsv has:
# name, reopen, keep, permanent, folder, startup command.
mm_def_records() {
    local file="$MACMOSH_HOME/desks.tsv" line
    [ -f "$file" ] || return 0
    while IFS= read -r line || [ -n "$line" ]; do
        mm_read_def "$line"
        mm_valid_desk_name "$d_name" || continue
        printf 'def\t%s\t%s\t%s\t%s\t%s\t%s\n' "$d_name" "$d_reopen" "$d_keep" "$d_permanent" "$d_folder" "$d_command"
    done < "$file"
}

cmd_status() {
    local os_version arch console server signins fv ar custom plain_pmset firewall_text sharing_line sharing agent_file
    os_version=$(sw_vers -productVersion 2>/dev/null)
    arch=$(uname -m 2>/dev/null)

    if mm_server_up; then
        server=up
        # The menu checks every 30 seconds, so a running server gets the hook soon after the script is updated.
        mm_set_hook
        mm_sweep_views
        # shellcheck disable=SC2016  # the command is expanded by the desk server's shell, not here
        signins=$(mm_tmux run-shell 'security show-keychain-info "$HOME/Library/Keychains/login.keychain-db" >/dev/null 2>&1 && echo ok || echo off' 2>/dev/null | head -n 1)
        case "$signins" in
            ok | off) ;;
            *) signins=unknown ;;
        esac
    else
        server=down
        signins=unknown
    fi

    case "$(fdesetup status 2>/dev/null | head -n 1)" in
        "FileVault is On"*) fv=on ;;
        "FileVault is Off"*) fv=off ;;
        *) fv=unknown ;;
    esac
    case "$(fdesetup supportsauthrestart 2>/dev/null | head -n 1)" in
        true) ar=yes ;;
        false) ar=no ;;
        *) ar=unknown ;;
    esac

    custom=$(pmset -g custom 2>/dev/null)
    plain_pmset=$(pmset -g 2>/dev/null)

    firewall_text=$(/usr/libexec/ApplicationFirewall/socketfilterfw --getglobalstate 2>/dev/null | head -n 1)
    case "$firewall_text" in
        *disabled*) firewall=off ;;
        *enabled*) firewall=on ;;
        *) firewall=unknown ;;
    esac

    sharing_line=$(launchctl print-disabled system 2>/dev/null | grep '"com.apple.screensharing"' | head -n 1)
    case "$sharing_line" in
        *"=> enabled"*) sharing=on ;;
        *"=> disabled"*) sharing=off ;;
        *) sharing=unknown ;;
    esac

    agent_file="$HOME/Library/LaunchAgents/$AGENT_LABEL.plist"

    {
        printf 'macmosh-host\t%s\t%s\n' "$MACMOSH_PROTOCOL" "$MACMOSH_HOST_VERSION"
        printf 'os\t%s\t%s\n' "$(mm_clean "$os_version")" "$(mm_clean "$arch")"
        console=$(mm_console_user)
        printf 'console\t%s\n' "$(mm_clean "$console")"
        printf 'server\t%s\n' "$server"
        printf 'signins\t%s\n' "$signins"
        printf 'filevault\t%s\n' "$fv"
        printf 'authrestart\t%s\n' "$ar"
        printf 'power\tsleep=%s\twomp=%s\tautorestart=%s\tdisablesleep=%s\n' \
            "$(mm_power_value sleep "$custom")" "$(mm_power_value womp "$custom")" \
            "$(mm_power_value autorestart "$custom")" "$(mm_lid_value "$plain_pmset")"
        mm_battery_record
        mm_home_record
        printf 'firewall\t%s\n' "$firewall"
        printf 'screensharing\t%s\n' "$sharing"
        if [ -f "$agent_file" ]; then
            printf 'agent\tinstalled\n'
        else
            printf 'agent\tmissing\n'
        fi
        mm_tool_records
        mm_desk_records
        mm_def_records
        printf 'end\n'
    }
    mm_log status "ok"
    return 0
}

# ---------------------------------------------------------------- main

usage() {
    cat >&2 <<EOF
usage: macmosh-host <subcommand>
  version   print the script version
  start     start the desk server if it is down
  status    print the status report
  attach [--cc] [--window @<id> | --new-window] [--label <word>] [--dry-run] <desk>
            --window opens this tab on one window of the desk, --new-window on a new one;
            other tabs on the desk stay where they are. --label names the tab for the
            status report (4 to 32 of 0-9 and a-f); with neither window option, the tab
            opens on the window the desk shows now
  desk-new <name> <folder> [--no-reopen] [--permanent] [--keep] [--command <text>]
            a new desk comes back after a restart unless --no-reopen, and is removed
            when its last shell exits unless --permanent
  desk-remove <name> [--kill]
  desk-rename <name> <new name>
            the desk keeps its windows, what runs in them and its settings
  desk-closed <desk> <pid>   run by the desk server when a desk's session closes
  keep <desk>   run the desk's startup command again each time it ends
  window-new <desk>
  window-name <desk> <window id> <name> | --auto
            names one window of the desk, given by its id (such as @3): 1 to 32 letters,
            digits, spaces, -, _ and full stops; with --auto it is named after its
            program again
  folders <folder>
  install-agent
  restart-server --yes
  uninstall --key <base64 key>
EOF
}

main() {
    local sub="${1:-}"
    case "$sub" in
        version)
            echo "$MACMOSH_HOST_VERSION"
            mm_log version "ok"
            ;;
        start)
            cmd_start
            ;;
        status)
            cmd_status
            ;;
        attach)
            shift
            cmd_attach "$@"
            ;;
        desk-new)
            shift
            cmd_desk_new "$@"
            ;;
        desk-remove)
            shift
            cmd_desk_remove "$@"
            ;;
        desk-rename)
            shift
            cmd_desk_rename "$@"
            ;;
        desk-closed)
            shift
            cmd_desk_closed "$@"
            ;;
        window-new)
            shift
            cmd_window_new "$@"
            ;;
        window-name)
            shift
            cmd_window_name "$@"
            ;;
        keep)
            shift
            cmd_keep "$@"
            ;;
        folders)
            shift
            cmd_folders "$@"
            ;;
        restart-server)
            shift
            cmd_restart_server "$@"
            ;;
        uninstall)
            shift
            cmd_uninstall "$@"
            ;;
        install-agent)
            cmd_install_agent
            ;;
        *)
            usage
            mm_log "${sub:-none}" "usage error"
            return 2
            ;;
    esac
}

main "$@"

"""#
}
